import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

// We import from the 'components' folder because that is where your files are
import Home from './components/Home';
import Register from './components/Register';
import Login from './components/Login';

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          {/* This is your main landing page (the email/password/google login) */}
          <Route path="/" element={<Home />} />
          
          {/* This is the page for registration */}
          <Route path="/register" element={<Register />} />
          
          {/* This is the separate login if you ever need it */}
          <Route path="/login" element={<Login />} />

          <Route path="/register" element={<Register />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
